// filterbar: the script of components/filterbar. First-party and written by
// hand (the file name is historical; nothing minifies it). See
// static/js/PROVENANCE.md for its behavior notes.
(function () {
  "use strict";

  // htmx runs a <script src> again when it arrives in swapped content (a
  // boosted navigation swaps the whole body). A second copy would add every
  // listener twice: one click would toggle a button on and off again and
  // send two requests. Same guard as theme-toggle.js and confirm.js.
  if (window.tui && window.tui.filterbar) return;

  var selectedCls = ["border-primary", "bg-primary", "text-primary-foreground"];
  var deselectedCls = ["border-border", "bg-background", "text-muted-foreground", "hover:bg-accent", "hover:text-accent-foreground"];

  function findBar(el) {
    return el.closest("[data-tui-filterbar]");
  }

  // applySets lets a selected <option> write into other controls of the bar:
  // data-tui-filterbar-set-<name>="<value>".
  function applySets(bar) {
    bar.querySelectorAll("select[data-tui-filterbar-control]").forEach(function (sel) {
      var opt = sel.options[sel.selectedIndex];
      if (!opt) return;
      Array.prototype.forEach.call(opt.attributes, function (a) {
        if (a.name.indexOf("data-tui-filterbar-set-") !== 0) return;
        var name = a.name.slice(23);
        bar.querySelectorAll("[data-tui-filterbar-control][name]").forEach(function (el) {
          if (el !== sel && el.getAttribute("name").toLowerCase() === name) {
            el.value = a.value;
          }
        });
      });
    });
  }

  function collectParams(bar) {
    var params = new URLSearchParams();
    bar.querySelectorAll("[data-tui-filterbar-control]").forEach(function (el) {
      var name = el.getAttribute("name");
      var val = el.value;
      if (name && val) {
        params.set(name, val);
      }
    });
    var toggleMap = {};
    bar.querySelectorAll('[data-tui-filterbar-toggle][data-tui-filterbar-toggle-selected="true"]').forEach(function (btn) {
      var name = btn.getAttribute("name");
      var val = btn.getAttribute("value");
      if (name && val) {
        if (!toggleMap[name]) {
          toggleMap[name] = [];
        }
        toggleMap[name].push(val);
      }
    });
    Object.keys(toggleMap).forEach(function (name) {
      params.set(name, toggleMap[name].join(","));
    });
    return params;
  }

  function cancelTimer(bar) {
    if (bar._wfFilterbarTimer) {
      clearTimeout(bar._wfFilterbarTimer);
      bar._wfFilterbarTimer = null;
    }
  }

  // triggerUpdate sends the bar's state now. A debounce timer still pending
  // is cancelled: this request carries what it would have sent. The bar is
  // the request's source element and carries hx-sync="this:replace", so htmx
  // aborts the bar's earlier request when it is still in flight: only the
  // answer to the newest request is swapped.
  function triggerUpdate(bar) {
    var hxGet = bar.getAttribute("data-tui-filterbar-hx-get");
    var hxTarget = bar.getAttribute("data-tui-filterbar-hx-target");
    var hxSwap = bar.getAttribute("data-tui-filterbar-hx-swap") || "innerHTML";
    cancelTimer(bar);
    // A bar that left the page (its debounce timer outlived a navigation)
    // sends nothing and does not rewrite the address of the page that
    // replaced it.
    if (!bar.isConnected) return;
    applySets(bar);
    var params = collectParams(bar);
    bar._wfFilterbarSent = params.toString();
    if (hxGet && typeof htmx !== "undefined") {
      var url = hxGet + (hxGet.indexOf("?") >= 0 ? "&" : "?") + params.toString();
      if (!bar.hasAttribute("hx-sync")) {
        bar.setAttribute("hx-sync", "this:replace");
      }
      // Without a target the answer goes to <body>, as it did when the
      // request had no source element.
      var sent = htmx.ajax("GET", url, { source: bar, target: hxTarget || "body", swap: hxSwap });
      // htmx rejects the promise of an aborted or failed request; its events
      // (htmx:sendAbort, htmx:sendError, ...) have reported it already.
      if (sent && sent.catch) {
        sent.catch(function () {});
      }
    }
    bar.dispatchEvent(new CustomEvent("filterbar-change", { bubbles: true, detail: { params: params } }));
    try {
      var u = new URL(window.location);
      bar.querySelectorAll("[data-tui-filterbar-control][name],[data-tui-filterbar-toggle][name]").forEach(function (el) {
        u.searchParams.delete(el.getAttribute("name"));
      });
      var drop = bar.getAttribute("data-tui-filterbar-drop");
      if (drop) {
        drop.split(",").forEach(function (k) {
          k = k.trim();
          if (k) {
            u.searchParams.delete(k);
          }
        });
      }
      params.forEach(function (v, k) {
        u.searchParams.set(k, v);
      });
      history.replaceState(null, "", u.toString());
    } catch (e) {}
  }

  function debouncedUpdate(bar, delay) {
    cancelTimer(bar);
    bar._wfFilterbarTimer = setTimeout(function () {
      bar._wfFilterbarTimer = null;
      triggerUpdate(bar);
    }, delay);
  }

  function swapClasses(el, remove, add) {
    remove.forEach(function (c) {
      el.classList.remove(c);
    });
    add.forEach(function (c) {
      el.classList.add(c);
    });
  }

  // setSelected marks a toggle pill or a choice button on or off.
  function setSelected(btn, on) {
    btn.setAttribute("data-tui-filterbar-toggle-selected", on ? "true" : "false");
    if (btn.hasAttribute("aria-pressed")) {
      btn.setAttribute("aria-pressed", on ? "true" : "false");
    }
    if (on) {
      swapClasses(btn, deselectedCls, selectedCls);
    } else {
      swapClasses(btn, selectedCls, deselectedCls);
    }
  }

  // chooseOne handles a click on btn in a single-choice group: btn alone
  // becomes selected; a click on the selected button deselects it, and the
  // group's "none" button (FilterConfig.Placeholder), when it has one, takes
  // over. It reports whether anything changed.
  function chooseOne(group, btn) {
    var none = group.querySelector("[data-tui-filterbar-choice-none]");
    var pick = btn;
    if (btn.getAttribute("data-tui-filterbar-toggle-selected") === "true") {
      if (btn === none) return false;
      pick = none;
    }
    group.querySelectorAll("[data-tui-filterbar-toggle]").forEach(function (b) {
      setSelected(b, b === pick);
    });
    return true;
  }

  // A choice group is one line that scrolls sideways. EDGE is the width of
  // the fade input.css draws on an edge that cuts buttons off.
  var EDGE = 32;

  // updateMore sets data-tui-filterbar-more to start, end or both while the
  // group has buttons scrolled out at that edge, and removes it otherwise.
  function updateMore(group) {
    var max = group.scrollWidth - group.clientWidth;
    var start = group.scrollLeft > 1;
    var end = group.scrollLeft < max - 1;
    var more = start && end ? "both" : start ? "start" : end ? "end" : "";
    if (more) {
      group.setAttribute("data-tui-filterbar-more", more);
    } else {
      group.removeAttribute("data-tui-filterbar-more");
    }
  }

  // reveal scrolls the group, never the page, until btn is clear of the
  // faded edges. At either end of the line there is no fade, and scrollLeft
  // stops there by itself.
  function reveal(group, btn) {
    if (!btn || group.clientWidth <= 0) return;
    var g = group.getBoundingClientRect();
    var b = btn.getBoundingClientRect();
    if (b.left < g.left + EDGE) {
      group.scrollLeft -= g.left + EDGE - b.left;
    } else if (b.right > g.right - EDGE) {
      group.scrollLeft += b.right - (g.right - EDGE);
    }
  }

  // showSelected reveals the group's selected option. The "none" button
  // does not count: with no option selected the group stays where the user
  // scrolled it.
  function showSelected(group) {
    reveal(group, group.querySelector('[data-tui-filterbar-toggle-selected="true"]:not([data-tui-filterbar-choice-none])'));
    updateMore(group);
  }

  // A button the keyboard focuses is revealed too, so the focus is never
  // under a fade (input.css also sets scroll-padding for the browser's own
  // scroll to a focused element).
  document.addEventListener("focusin", function (e) {
    var btn = e.target.closest && e.target.closest("[data-tui-filterbar-toggle]");
    var group = btn && btn.closest("[data-tui-filterbar-choice]");
    if (!group) return;
    reveal(group, btn);
    updateMore(group);
  });

  // A group's width changes without a window resize (a slide-over opens, a
  // sidebar folds), so each group is watched; a removed group is let go.
  var watcher = window.ResizeObserver
    ? new ResizeObserver(function (entries) {
        entries.forEach(function (entry) {
          if (!entry.target.isConnected) {
            watcher.unobserve(entry.target);
            return;
          }
          showSelected(entry.target);
        });
      })
    : null;

  // scanChoices runs after the page load, every htmx swap and a window
  // resize. A group it has not seen is a fresh render: its selected option
  // is brought into view. A group it has seen only gets its edge marks
  // again, so a swap elsewhere on the page never moves a group the user
  // scrolled.
  function scanChoices() {
    document.querySelectorAll("[data-tui-filterbar-choice]").forEach(function (group) {
      if (group._wfFilterbarSeen) {
        updateMore(group);
        return;
      }
      group._wfFilterbarSeen = true;
      if (watcher) {
        watcher.observe(group);
      }
      showSelected(group);
    });
  }

  function resetAll(bar) {
    bar.querySelectorAll("[data-tui-filterbar-control]").forEach(function (el) {
      if (el.type === "hidden" || el.hasAttribute("data-tui-filterbar-state")) {
        return;
      }
      if (el.tagName === "SELECT") {
        el.selectedIndex = 0;
      } else {
        el.value = "";
      }
    });
    bar.querySelectorAll("[data-tui-filterbar-toggle]").forEach(function (btn) {
      setSelected(btn, btn.hasAttribute("data-tui-filterbar-choice-none"));
    });
    bar.querySelectorAll("[data-tui-filterbar-choice]").forEach(showSelected);
    triggerUpdate(bar);
  }

  // A browser fires change on a text input when it loses focus after an edit
  // and on Enter. For a debounced control the input listener has sent, or
  // will send, that edit already. So: with the timer pending, send now in
  // its place (Enter, or the focus left before the debounce time was over);
  // with the bar's parameters equal to those of its last request, send
  // nothing.
  document.addEventListener("change", function (e) {
    var el = e.target.closest("[data-tui-filterbar-control]");
    if (!el) return;
    var bar = findBar(el);
    if (!bar) return;
    if (el.hasAttribute("data-tui-filterbar-debounce") && !bar._wfFilterbarTimer) {
      applySets(bar);
      if (collectParams(bar).toString() === bar._wfFilterbarSent) return;
    }
    triggerUpdate(bar);
  });

  document.addEventListener("input", function (e) {
    var el = e.target.closest("[data-tui-filterbar-control][data-tui-filterbar-debounce]");
    if (!el) return;
    var bar = findBar(el);
    if (!bar) return;
    var delay = parseInt(el.getAttribute("data-tui-filterbar-debounce"), 10) || 300;
    debouncedUpdate(bar, delay);
  });

  document.addEventListener("click", function (e) {
    var bar;
    var toggle = e.target.closest("[data-tui-filterbar-toggle]");
    if (toggle) {
      var group = toggle.closest("[data-tui-filterbar-choice]");
      if (group) {
        if (!chooseOne(group, toggle)) return;
        showSelected(group);
      } else {
        setSelected(toggle, toggle.getAttribute("data-tui-filterbar-toggle-selected") !== "true");
      }
      bar = findBar(toggle);
      if (bar) triggerUpdate(bar);
      return;
    }
    var reset = e.target.closest("[data-tui-filterbar-reset]");
    if (reset) {
      bar = findBar(reset);
      if (bar) resetAll(bar);
      return;
    }
  });

  // A response may render a control again out of band (filterbar.ControlsOOB
  // and HiddenOOB: an element with the control's id and hx-swap-oob). A
  // control that would look the same afterwards is not replaced at all, so
  // nothing changes under the pointer. Otherwise two things would be lost
  // with the old element and are kept here. A <select> that has the focus
  // is not replaced: its open list would close. A group of buttons is
  // replaced; its sideways scroll position, and the focus when one of its
  // buttons had it, are put back on the new element.
  var replaced = {};

  // controlState describes what a control shows and sends: for a <select>
  // its value and each option's value, text and attributes; for a group
  // each button's value, text and whether it is selected. Two elements with
  // the same state differ in nothing the user can see or the bar collects
  // (class order and the script's own marks are left out).
  function controlState(el) {
    var parts = [el.tagName, el.getAttribute("name") || ""];
    if (el.tagName === "SELECT") {
      parts.push(el.value);
      Array.prototype.forEach.call(el.options, function (opt) {
        var attrs = Array.prototype.filter
          .call(opt.attributes, function (a) {
            return a.name !== "selected";
          })
          .map(function (a) {
            return a.name + "=" + a.value;
          })
          .sort();
        parts.push(opt.textContent.trim() + "\u0001" + attrs.join("\u0001"));
      });
    } else {
      parts.push(el.getAttribute("aria-labelledby") || el.getAttribute("aria-label") || "");
      el.querySelectorAll("[data-tui-filterbar-toggle]").forEach(function (btn) {
        parts.push(
          [
            btn.getAttribute("name"),
            btn.getAttribute("value"),
            btn.getAttribute("data-tui-filterbar-toggle-selected"),
            btn.hasAttribute("data-tui-filterbar-choice-none") ? "none" : "",
            btn.textContent.replace(/\s+/g, " ").trim(),
          ].join("\u0001")
        );
      });
    }
    return parts.join("\u0002");
  }

  document.addEventListener("htmx:oobBeforeSwap", function (e) {
    var target = e.detail && e.detail.target;
    if (!target || !target.id || !target.closest || !findBar(target)) return;
    var active = document.activeElement;
    var isSelect = target.tagName === "SELECT";
    var isGroup = target.hasAttribute("data-tui-filterbar-choice") || !!target.querySelector("[data-tui-filterbar-toggle]");
    var incoming = e.detail.fragment && e.detail.fragment.firstElementChild;
    if ((isSelect || isGroup) && incoming && incoming.tagName === target.tagName && controlState(incoming) === controlState(target)) {
      e.detail.shouldSwap = false;
      return;
    }
    if (isSelect) {
      if (target === active) {
        e.detail.shouldSwap = false;
      }
      return;
    }
    if (isGroup) {
      replaced[target.id] = {
        scrollLeft: target.scrollLeft,
        focus: active && target.contains(active) ? active.getAttribute("value") : null,
      };
    }
  });

  function restoreReplaced() {
    Object.keys(replaced).forEach(function (id) {
      var was = replaced[id];
      delete replaced[id];
      var group = document.getElementById(id);
      if (!group) return;
      group.scrollLeft = was.scrollLeft;
      if (was.focus !== null && (!document.activeElement || document.activeElement === document.body)) {
        Array.prototype.some.call(group.querySelectorAll("[data-tui-filterbar-toggle]"), function (btn) {
          if (btn.getAttribute("value") !== was.focus) return false;
          btn.focus({ preventScroll: true });
          return true;
        });
      }
      if (group.hasAttribute("data-tui-filterbar-choice")) {
        showSelected(group);
      }
    });
  }
  document.addEventListener("htmx:oobAfterSwap", restoreReplaced);
  document.addEventListener("htmx:afterSettle", restoreReplaced);

  // scroll does not bubble: listen in the capture phase.
  document.addEventListener(
    "scroll",
    function (e) {
      if (e.target.matches && e.target.matches("[data-tui-filterbar-choice]")) {
        updateMore(e.target);
      }
    },
    true
  );
  window.addEventListener("resize", scanChoices);
  document.addEventListener("htmx:afterSettle", scanChoices);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", scanChoices);
  } else {
    scanChoices();
  }

  window.tui = window.tui || {};
  window.tui.filterbar = { getParams: collectParams, trigger: triggerUpdate, reset: resetAll };
})();
